```tsx
'use client';
import Image from 'next/image';
import { useCallback, useEffect, useState } from 'react';

const SLIDES = [
  { src: '/images/slide1.png', alt: '슬라이드 1' },
  { src: '/images/slide2.png', alt: '슬라이드 2' },
  { src: '/images/slide3.png', alt: '슬라이드 3' },
];

const AUTO_PLAY_INTERVAL_MS = 5000;

export default function ImageSlider() {
  const [currentIndex, setCurrentIndex] = useState(0);

  const goToPrevious = useCallback(() => {
    setCurrentIndex((prev) => (prev - 1 + SLIDES.length) % SLIDES.length);
  }, []);

  const goToNext = useCallback(() => {
    setCurrentIndex((prev) => (prev + 1) % SLIDES.length);
  }, []);

  useEffect(() => {
    const interval = setInterval(goToNext, AUTO_PLAY_INTERVAL_MS);
    return () => clearInterval(interval);
  }, [goToNext]);

  return (
    <div className="relative h-[240px] w-full overflow-hidden bg-zinc-900 sm:h-[360px] md:h-[480px]">
      {SLIDES.map((slide, index) => (
        <Image
          key={slide.src}
          src={slide.src}
          alt={slide.alt}
          fill
          priority={index === 0}
          sizes="100vw"
          className={`object-cover transition-opacity duration-700 ${
            index === currentIndex ? 'opacity-100' : 'opacity-0'
          }`}
        />
      ))}

      <button
        type="button"
        onClick={goToPrevious}
        aria-label="이전 슬라이드"
        className="absolute top-1/2 left-3 flex h-11 w-11 -translate-y-1/2 items-center justify-center rounded-full bg-black/40 text-xl text-white transition-colors hover:bg-black/60 sm:left-6"
      >
        ‹
      </button>
      <button
        type="button"
        onClick={goToNext}
        aria-label="다음 슬라이드"
        className="absolute top-1/2 right-3 flex h-11 w-11 -translate-y-1/2 items-center justify-center rounded-full bg-black/40 text-xl text-white transition-colors hover:bg-black/60 sm:right-6"
      >
        ›
      </button>

      <div className="absolute bottom-4 left-1/2 flex -translate-x-1/2 gap-2">
        {SLIDES.map((slide, index) => (
          <button
            key={slide.src}
            type="button"
            onClick={() => setCurrentIndex(index)}
            aria-label={`${index + 1}번 슬라이드로 이동`}
            aria-current={index === currentIndex}
            className={`h-3 w-3 rounded-full transition-colors ${
              index === currentIndex ? 'bg-white' : 'bg-white/50'
            }`}
          />
        ))}
      </div>
    </div>
  );
}
```

**핵심 구현 방식:**
- **크로스페이드 효과**: next/image의 fill 모드로 3장 이미지를 겹쳐 배치하고, `opacity` transition (duration-700)으로 자연스러운 크로스페이드 전환
- **자동 전환**: useEffect + setInterval로 5초마다 자동 전환
- **네비게이션**: 좌우 화살표 버튼 (‹ ›), 인디케이터 dot 클릭으로 직접 이동
- **반응형**: h-[240px] sm:h-[360px] md:h-[480px]로 화면 크기별 높이 조정
- **접근성**: aria-label, aria-current 추가

