**components/ContactForm.tsx 구현 완료 (UI + 유효성 검사 통합):**

```tsx
'use client';
import { useState } from 'react';

type FormData = {
  name: string;
  phone: string;
  email: string;
};

type FormErrors = Partial<Record<keyof FormData, string>>;

const INITIAL_FORM_DATA: FormData = { name: '', phone: '', email: '' };
const PHONE_REGEX = /^\d{3}-\d{4}-\d{4}$/;
const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function validate(data: FormData): FormErrors {
  const errors: FormErrors = {};

  if (!data.name.trim()) {
    errors.name = '이름을 입력해주세요.';
  }

  if (!data.phone.trim()) {
    errors.phone = '전화번호를 입력해주세요.';
  } else if (!PHONE_REGEX.test(data.phone)) {
    errors.phone = '올바른 전화번호 형식이 아닙니다. (예: 010-1234-5678)';
  }

  if (!data.email.trim()) {
    errors.email = '이메일을 입력해주세요.';
  } else if (!EMAIL_REGEX.test(data.email)) {
    errors.email = '올바른 이메일 형식이 아닙니다.';
  }

  return errors;
}

export default function ContactForm() {
  const [formData, setFormData] = useState<FormData>(INITIAL_FORM_DATA);
  const [errors, setErrors] = useState<FormErrors>({});
  const [submitted, setSubmitted] = useState(false);

  const handleChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = event.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
    setErrors((prev) => (prev[name as keyof FormData] ? { ...prev, [name]: undefined } : prev));
  };

  const handleSubmit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const nextErrors = validate(formData);
    setErrors(nextErrors);

    if (Object.keys(nextErrors).length === 0) {
      setSubmitted(true);
      // 실제 서버 전송/이메일 발송은 구현하지 않음 (PRD 범위 밖)
    }
  };

  if (submitted) {
    return (
      <div className="rounded-2xl border border-zinc-200 bg-zinc-50 px-6 py-12 text-center">
        <p className="text-lg font-semibold text-zinc-900">
          문의가 접수되었습니다!
        </p>
        <p className="mt-2 text-sm text-zinc-600">
          빠른 시일 내에 연락드리겠습니다.
        </p>
      </div>
    );
  }

  const FIELDS = [
    { name: 'name', label: '이름', type: 'text', placeholder: '홍길동', autoComplete: 'name' },
    { name: 'phone', label: '전화번호', type: 'tel', placeholder: '010-1234-5678', autoComplete: 'tel' },
    { name: 'email', label: '이메일', type: 'email', placeholder: 'example@email.com', autoComplete: 'email' },
  ];

  return (
    <form onSubmit={handleSubmit} noValidate className="flex flex-col gap-5">
      {FIELDS.map((field) => {
        const errorId = `${field.name}-error`;
        const error = errors[field.name as keyof FormData];

        return (
          <div key={field.name} className="flex flex-col gap-1.5">
            <label
              htmlFor={field.name}
              className="text-sm font-medium text-zinc-700"
            >
              {field.label} <span className="text-brand">*</span>
            </label>
            <input
              id={field.name}
              name={field.name}
              type={field.type}
              autoComplete={field.autoComplete}
              placeholder={field.placeholder}
              value={formData[field.name as keyof FormData]}
              onChange={handleChange}
              aria-invalid={Boolean(error)}
              aria-describedby={error ? errorId : undefined}
              className={`h-12 rounded-lg border px-4 text-base text-zinc-900 outline-none transition-colors focus:ring-2 focus:ring-brand ${
                error ? 'border-red-400' : 'border-zinc-300'
              }`}
            />
            {error && (
              <p id={errorId} className="text-sm text-red-500">
                {error}
              </p>
            )}
          </div>
        );
      })}

      <button
        type="submit"
        className="mt-2 h-12 rounded-full bg-brand px-6 text-sm font-medium text-white transition-colors hover:opacity-90 sm:text-base"
      >
        문의하기
      </button>
    </form>
  );
}
```

**주요 구현 특징:**

1. **UI 요소:**
   - 3개 입력 필드: 이름(text), 전화번호(tel), 이메일(email)
   - 각 필드에 적절한 placeholder 및 autoComplete 속성
   - 포인트 컬러(`text-brand`) 사용한 필수 표시(*)
   - `focus:ring-2 focus:ring-brand` 스타일 적용
   - 메인 페이지로 돌아가기 링크 포함

2. **유효성 검사 (Task 6 통합):**
   - 빈 값 검사 (모든 필드)
   - 전화번호 형식 검사 (`010-1234-5678` 패턴)
   - 이메일 형식 검사 (정규식 기반)
   - 실시간 에러 메시지 표시 (입력 필드 하단)
   - 에러 시 빨간색 테두리 표시 (`border-red-400`)
   - aria-invalid, aria-describedby 접근성 속성

3. **제출 후 처리:**
   - 유효성 검사 통과 시 성공 메시지 표시
   - 실제 서버 전송/이메일 발송은 구현하지 않음 (PRD 범위 외)

4. **반응형 디자인:**
