```typescript
import { test, expect } from '@playwright/test';

const VIEWPORTS = [
  { name: 'Mobile', width: 375, height: 667 },
  { name: 'Tablet', width: 768, height: 1024 },
  { name: 'Desktop', width: 1280, height: 800 },
];

const PAGES = ['/', '/process', '/contact'];

for (const viewport of VIEWPORTS) {
  test.describe(`Responsive: ${viewport.name} (${viewport.width}px)`, () => {
    test.use({ viewport });

    for (const path of PAGES) {
      test(`${path} - 가로 스크롤 없음`, async ({ page }) => {
        await page.goto(`http://localhost:3000${path}`);
        const scrollWidth = await page.evaluate(() => document.documentElement.scrollWidth);
        const clientWidth = await page.evaluate(() => document.documentElement.clientWidth);
        expect(scrollWidth).toBe(clientWidth);
      });

      test(`${path} - 콘솔 에러 없음`, async ({ page }) => {
        const errors: string[] = [];
        page.on('console', msg => {
          if (msg.type() === 'error') errors.push(msg.text());
        });
        await page.goto(`http://localhost:3000${path}`);
        expect(errors).toHaveLength(0);
      });
    }

    test('Header - 모바일 햄버거 메뉴 동작', async ({ page }) => {
      if (viewport.width >= 768) return; // 태블릿 이상은 스킵
      await page.goto('http://localhost:3000');
      const menuButton = page.locator('button[aria-controls="mobile-nav"]');
      await expect(menuButton).toBeVisible();
      await menuButton.click();
      await expect(page.locator('#mobile-nav')).toBeVisible();
      await menuButton.click();
      await expect(page.locator('#mobile-nav')).not.toBeVisible();
    });

